import { getCurrentSunColor } from "game/entities/utils";
import { GameScene } from "../GameScene";
import { gameConfig } from "game/config";

export const maxSunPosition = 4;

export class Sun {
  constructor(scene: GameScene) {
    this.scene = scene;

    scene.lights.enable().setAmbientColor(this.getCurrentColor());

    const tween = scene.tweens.add({
      targets: this.scene.sceneConfig.currentTime,
      duration: gameConfig.dayCircleTimeInRealSeconds * 1000,
      time: maxSunPosition,
      onUpdate: (value) => {
        console.log(value);
      },
    });
  }
  private scene: GameScene;

  private getCurrentColor = () => {
    if (this.scene.sceneConfig.currentTime >= maxSunPosition) {
      this.scene.sceneConfig.currentTime = 0;
    }

    const { currentTime, dayLighting } = this.scene.sceneConfig;
    const currentColor = getCurrentSunColor(currentTime, dayLighting);
    return currentColor;
  };

  update = () => {
    const color = this.getCurrentColor();
    this.scene.lights.setAmbientColor(color);
  };
}
